using CustomCodeFramework.Redis.Abstractions;using CustomCodeFramework.Redis.Caching;using Dhole.Content.Application.Abstractions.Cache;using Dhole.Content.Contracts.ContentItems;using Dhole.Content.Contracts.Navigation;using Dhole.Content.Contracts.Settings;namespace Dhole.Content.Infrastructure.Cache;
public sealed class ContentCacheService(ICacheService cache):IContentCacheService
{private static readonly TimeSpan DefaultExpiration=TimeSpan.FromMinutes(30);public Task<ContentItemDto?> GetPublishedContentAsync(string siteKey,string slug,string locale,CancellationToken ct=default)=>cache.GetAsync<ContentItemDto>(ContentCacheKeys.PublishedContent(siteKey,slug,locale),ct);public Task SetPublishedContentAsync(string siteKey,string slug,string locale,ContentItemDto value,TimeSpan? expiration=null,CancellationToken ct=default)=>cache.SetAsync(ContentCacheKeys.PublishedContent(siteKey,slug,locale),value,CacheEntryOptions.Default(expiration??DefaultExpiration),ct);public async Task RemoveContentAsync(string siteKey,string slug,CancellationToken ct=default){foreach(var locale in new[]{"es-CR","en-US","es","en"})await cache.RemoveAsync(ContentCacheKeys.PublishedContent(siteKey,slug,locale),ct);}public Task<NavigationMenuDto?> GetMenuAsync(string siteKey,string location,CancellationToken ct=default)=>cache.GetAsync<NavigationMenuDto>(ContentCacheKeys.Menu(siteKey,location),ct);public Task SetMenuAsync(string siteKey,string location,NavigationMenuDto value,TimeSpan? expiration=null,CancellationToken ct=default)=>cache.SetAsync(ContentCacheKeys.Menu(siteKey,location),value,CacheEntryOptions.Default(expiration??DefaultExpiration),ct);public Task RemoveMenuAsync(string siteKey,string location,CancellationToken ct=default)=>cache.RemoveAsync(ContentCacheKeys.Menu(siteKey,location),ct);public Task<IReadOnlyCollection<SiteSettingDto>?> GetPublicSettingsAsync(string siteKey,CancellationToken ct=default)=>cache.GetAsync<IReadOnlyCollection<SiteSettingDto>>(ContentCacheKeys.Settings(siteKey),ct);public Task SetPublicSettingsAsync(string siteKey,IReadOnlyCollection<SiteSettingDto> value,TimeSpan? expiration=null,CancellationToken ct=default)=>cache.SetAsync(ContentCacheKeys.Settings(siteKey),value,CacheEntryOptions.Default(expiration??DefaultExpiration),ct);public Task RemovePublicSettingsAsync(string siteKey,CancellationToken ct=default)=>cache.RemoveAsync(ContentCacheKeys.Settings(siteKey),ct);}
